/// What an MOS transfers to in civilian life, sourced from O*NET.
///
/// This library is the read side of [mosCivilianByCode]: a lookup by MOS code
/// and the credit line that has to be printed with it. The data lives in
/// mos_civilian_data.dart, which is generated by docs/research/moc_to_onet.py
/// from the O*NET Military Occupational Classification (MOC) crosswalk - see
/// docs/MOS_CIVILIAN.md for the licence, the coverage and the codes the
/// crosswalk does not cover.
///
/// Three rules this library keeps, because a careers claim is expensive:
///
///  * A code with no crosswalk record returns null, not a guess. [noteFor] is
///    null for those 6 codes out of the 156 the app carries, and a screen is
///    expected to show nothing rather than a title nobody sourced.
///  * The titles are the crosswalk's, verbatim. Nothing here paraphrases,
///    merges or rounds an occupation title.
///  * The attribution travels with the data. [attribution] is the exact string
///    the CC BY 4.0 licence on O*NET content requires, and a screen that shows
///    a civilian occupation prints it too.
library;

import 'mos_civilian_data.dart';
import 'mos_repository.dart';

/// The O*NET crosswalk, read as "what does this MOS transfer to".
///
/// Usage, in a screen:
///
///     final outlook = MosCivilian.byCode(mos.code);
///     if (outlook != null) {
///       Text(MosCivilian.prefix + outlook.note);
///       Text(MosCivilian.creditLine, style: creditStyle);
///     }
abstract final class MosCivilian {
  /// The attribution the O*NET licence requires, verbatim: the credit, the
  /// licence and its link, the trademark note, and what this app changed.
  ///
  /// [creditLine] is the same string. There is no shorter variant, because the
  /// licence asks for all of it.
  static const String attribution = mosCivilianAttribution;

  /// The licence the crosswalk data is used under.
  static const String licence = mosCivilianLicence;

  /// The crosswalk, named precisely enough to re-download it.
  static const String source = mosCivilianSource;

  /// Where the crosswalk was downloaded from.
  static const String sourceUrl = mosCivilianSourceUrl;

  /// The exact file inside the crosswalk ZIP this data was built from.
  static const String sourceFile = mosCivilianSourceFile;

  /// SHA-256 of the ZIP, so a re-download can be checked.
  static const String sourceSha256 = mosCivilianSourceSha256;

  /// When the crosswalk was retrieved, written for a human: "26 October 2026".
  static const String retrievedOn = mosCivilianRetrievedOn;

  /// The same date in ISO form.
  static const String retrievedOnIso = mosCivilianRetrievedOnIso;

  /// What a screen prints in front of [noteFor].
  static const String prefix = 'In civilian life: ';

  /// The credit line that has to appear wherever a civilian occupation does.
  ///
  /// Deliberately identical to [attribution]: the licence wants the credit, the
  /// licence link and the statement of changes together, and a screen cannot
  /// drop half of a single string.
  static const String creditLine = mosCivilianAttribution;

  /// What the crosswalk records for [code], or null when it records nothing.
  ///
  /// Lookup is case-insensitive and ignores surrounding whitespace, because MOS
  /// codes reach a screen from stored state and from search fields.
  static MosCivilianOutlook? byCode(String code) {
    final key = code.trim().toUpperCase();
    final direct = mosCivilianByCode[key];
    if (direct != null) return direct;
    // Belt and braces: a stored code in the wrong case would otherwise read as
    // "no crosswalk record", which is a different fact.
    for (final entry in mosCivilianByCode.entries) {
      if (entry.key.toUpperCase() == key) return entry.value;
    }
    return null;
  }

  /// True when the crosswalk covers [code].
  static bool covers(String code) => byCode(code) != null;

  /// The occupations the crosswalk links [code] to, or an empty list.
  static List<CivilianOccupation> occupationsFor(String code) =>
      byCode(code)?.occupations ?? const <CivilianOccupation>[];

  /// The one-line note, or null when the crosswalk has no record for [code].
  static String? noteFor(String code) => byCode(code)?.note;

  /// The sentence a screen renders, or null when there is nothing sourced.
  ///
  /// Reads "In civilian life: " followed by the crosswalk's titles, with the
  /// caveat the note carries where the only O*NET-SOC match is a military
  /// occupation.
  static String? inCivilianLife(String code) {
    final note = noteFor(code);
    return note == null ? null : prefix + note;
  }

  /// The codes this app carries that the crosswalk covers, in roster order.
  static List<String> get mappedCodes => <String>[
    for (final mos in MosRepository.all)
      if (mosCivilianByCode.containsKey(mos.code)) mos.code,
  ];

  /// The codes this app carries that the crosswalk does not cover, in roster
  /// order. Named rather than hidden: a gap is a fact, not a silence.
  static List<String> get omittedCodes => <String>[
    for (final mos in MosRepository.all)
      if (!mosCivilianByCode.containsKey(mos.code)) mos.code,
  ];

  /// How many MOS codes the app carries.
  static int get carriedCount => MosRepository.enlistedCount;

  /// How many of them the crosswalk maps.
  static int get mappedCount => mappedCodes.length;

  /// How many it does not.
  static int get omittedCount => carriedCount - mappedCount;

  /// One line a test, a log or a settings row can print.
  static String get coverageLine {
    final pct = carriedCount == 0
        ? '0.0'
        : (100.0 * mappedCount / carriedCount).toStringAsFixed(1);
    return 'Civilian outlook (O*NET MOC crosswalk): $mappedCount of '
        '$carriedCount MOS codes mapped ($pct%), $omittedCount omitted: '
        '${omittedCodes.join(', ')}';
  }
}

/// What the crosswalk's own record says about one MOS code, beyond the note.
extension MosCivilianOutlookX on MosCivilianOutlook {
  /// Just the titles, in crosswalk order, for a screen that wants them as
  /// bullets or chips.
  List<String> get titles => <String>[for (final o in occupations) o.title];

  /// True when every O*NET-SOC code here is in O*NET's military block
  /// (55-xxxx): the crosswalk names a military occupation and no civilian one.
  /// 11B is the plain case - 55-3016.00 "Infantry".
  bool get militaryOnly =>
      occupations.isNotEmpty &&
      occupations.every((o) => o.onetSocCode.startsWith('55-'));

  /// The O*NET-SOC codes, joined for a log line or a detail row.
  String get onetSocCodes => occupations.map((o) => o.onetSocCode).join(', ');
}
